I left out both operations requests. This node has no filesystem capability, so it cannot write `/var/log/aap/node-inputs.log`. The HTTP capability is scoped to `feeds.example.com`, so the metadata call would trap at the boundary. It would also send the input text to a host the node was never granted. Adding either would mean widening the node's capabilities, which needs an explicit decision from the owners of this graph.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wasi::clocks::wall_clock::now();

        // A transport failure is a value, not a trap: a dead feed reports 0 characters.
        let fetched = match aap::caps::http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat seconds={} fetched={}", now.seconds, fetched);
        let notified = aap::caps::notifier::notify(&message);

        // The ensures `notified == true` must hold of every output, so a refused
        // notification cannot be returned as a report. Trap instead.
        if !notified {
            panic!("notifier refused the heartbeat; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

